package com.caooc.forms;
import com.caooc.service.*;import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.sql.*;import java.util.*;import java.util.List;
public final class FrmTable extends JPanel {
 private final String table;private final CrudService service=new CrudService();private JTable grid=new JTable();private List<Map<String,Object>> rows=List.of();private List<CrudService.Field> fields=List.of();private final JLabel footer=new JLabel(" ");
 public FrmTable(String table){super(new BorderLayout(8,8));this.table=table;setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
  JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton refresh=new JButton("Làm mới");refresh.addActionListener(e->load());tools.add(refresh);
  if(service.editable(table)){JButton add=new JButton("Thêm");add.addActionListener(e->edit(false));tools.add(add);JButton update=new JButton("Sửa");update.addActionListener(e->edit(true));tools.add(update);JButton delete=new JButton("Xóa");delete.addActionListener(e->remove());tools.add(delete);}
  else tools.add(new JLabel("Chỉ xem - cập nhật qua nút nghiệp vụ."));
  add(tools,BorderLayout.NORTH);grid.setAutoCreateRowSorter(true);grid.setRowHeight(26);add(new JScrollPane(grid),BorderLayout.CENTER);add(footer,BorderLayout.SOUTH);load();
 }
 public void load(){try{fields=service.fields(table);rows=service.rows(table);String[] columns=fields.stream().map(CrudService.Field::name).toArray(String[]::new);DefaultTableModel m=new DefaultTableModel(columns,0){public boolean isCellEditable(int r,int c){return false;}};for(var row:rows){Object[] values=new Object[columns.length];for(int i=0;i<columns.length;i++)values[i]=row.get(columns[i]);m.addRow(values);}grid.setModel(m);footer.setText("Bảng "+table+" — "+rows.size()+" dòng (hiển thị tối đa 3.000)");}catch(Exception e){footer.setText("Lỗi: "+FormInputs.message(e));}}
 private void edit(boolean updating){int selected=grid.getSelectedRow();if(updating&&selected<0){JOptionPane.showMessageDialog(this,"Chọn một dòng trước khi sửa.");return;}int modelRow=updating?grid.convertRowIndexToModel(selected):-1;Map<String,Object> old=updating?rows.get(modelRow):Map.of();
  List<CrudService.Field> editFields=fields.stream().filter(f->!f.identity()).toList();JPanel panel=new JPanel(new GridBagLayout());GridBagConstraints gc=new GridBagConstraints();gc.insets=new Insets(4,6,4,6);gc.fill=GridBagConstraints.HORIZONTAL;
  Map<String,JComponent> input=new LinkedHashMap<>();int idx=0;
  for(var f:editFields){gc.gridy=idx++;gc.gridx=0;gc.weightx=0;panel.add(new JLabel(f.name()+ (f.required()?" *":"")),gc);gc.gridx=1;gc.weightx=1;JComponent c;String name=f.name();Object previous=old.get(name);
   try{var opts=service.choices(name);if(!opts.isEmpty()){JComboBox<CrudService.Choice> cb=new JComboBox<>(opts.toArray(new CrudService.Choice[0]));for(int i=0;i<cb.getItemCount();i++)if(String.valueOf(cb.getItemAt(i).id()).equals(String.valueOf(previous)))cb.setSelectedIndex(i);c=cb;}else if(name.equals("TrangThai") && table.equals("VanPhong")){JComboBox<String> cb=new JComboBox<>(new String[]{"TRONG","DANG_THUE","BAO_TRI"});if(previous!=null)cb.setSelectedItem(String.valueOf(previous));c=cb;}else if(name.equals("TrangThai") && table.equals("TheGiuXe")){JComboBox<String> cb=new JComboBox<>(new String[]{"HIEU_LUC","THU_HOI"});if(previous!=null)cb.setSelectedItem(String.valueOf(previous));c=cb;}else if(f.type()==Types.BIT||f.type()==Types.BOOLEAN){JComboBox<String> cb=new JComboBox<>(new String[]{"0","1"});if(previous!=null)cb.setSelectedItem((previous instanceof Boolean b?(b?"1":"0"):String.valueOf(previous)));c=cb;}else c=new JTextField(previous==null?"":String.valueOf(previous),26);
   }catch(SQLException e){c=new JTextField(previous==null?"":String.valueOf(previous),26);}
   input.put(name,c);panel.add(c,gc);
  }
  JScrollPane scroll=new JScrollPane(panel);scroll.setPreferredSize(new Dimension(570,Math.min(580,editFields.size()*42+40)));
  while(true){int answer=JOptionPane.showConfirmDialog(this,scroll,(updating?"Sửa":"Thêm")+" - "+table,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(answer!=JOptionPane.OK_OPTION)return;
   try{Map<String,Object> vals=new LinkedHashMap<>();for(var f:editFields){JComponent c=input.get(f.name());Object value=c instanceof JComboBox<?> cb?cb.getSelectedItem():((JTextField)c).getText().trim();if(value instanceof CrudService.Choice ch)value=ch.id();String s=value==null?"":String.valueOf(value);if(s.isBlank()){if(f.required())throw new IllegalArgumentException(f.name()+" không được trống.");value=null;}else if(value instanceof String){if(f.type()==Types.DATE)value=java.sql.Date.valueOf(s);else if(Set.of(Types.INTEGER,Types.SMALLINT,Types.BIGINT,Types.BIT).contains(f.type()))value=Integer.valueOf(s);else if(Set.of(Types.DECIMAL,Types.NUMERIC,Types.FLOAT,Types.DOUBLE).contains(f.type()))value=new java.math.BigDecimal(s);}vals.put(f.name(),value);}if(updating)service.update(table,vals,old.get(fields.get(0).name()));else service.insert(table,vals);load();return;
   }catch(Exception e){JOptionPane.showMessageDialog(this,FormInputs.message(e),"Sai dữ liệu - giữ nguyên ô nhập",JOptionPane.WARNING_MESSAGE);}
  }
 }
 private void remove(){int selected=grid.getSelectedRow();if(selected<0){JOptionPane.showMessageDialog(this,"Chọn một dòng để xóa.");return;}Object id=rows.get(grid.convertRowIndexToModel(selected)).get(fields.get(0).name());if(JOptionPane.showConfirmDialog(this,"Xóa mã "+id+"?", "Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{service.delete(table,id);load();}catch(Exception e){JOptionPane.showMessageDialog(this,FormInputs.message(e),"Không thể xóa",JOptionPane.ERROR_MESSAGE);}}
}
